"""Write version_info.txt (a Windows VERSIONINFO resource) from tsunami.__version__.

Run by tsunami.spec and build.ps1, so the version is never edited by hand.
Standalone: uv run python packaging/make_version_info.py
"""

from __future__ import annotations

import re
from pathlib import Path

HERE = Path(__file__).parent
INIT = HERE.parent / "src" / "tsunami" / "__init__.py"
OUT = HERE / "version_info.txt"

TEMPLATE = """# UTF-8
# Generated by packaging/make_version_info.py. Do not edit.
VSVersionInfo(
  ffi=FixedFileInfo(
    filevers=({a}, {b}, {c}, 0),
    prodvers=({a}, {b}, {c}, 0),
    mask=0x3f,
    flags=0x0,
    OS=0x40004,
    fileType=0x1,
    subtype=0x0,
    date=(0, 0)
  ),
  kids=[
    StringFileInfo([
      StringTable(
        '040904B0',
        [StringStruct('CompanyName', 'Tsunami'),
         StringStruct('FileDescription', 'Tsunami network configuration tool'),
         StringStruct('FileVersion', '{version}'),
         StringStruct('InternalName', 'tsunami'),
         StringStruct('LegalCopyright', 'Copyright (c) Tsunami contributors'),
         StringStruct('OriginalFilename', 'tsunami.exe'),
         StringStruct('ProductName', 'Tsunami'),
         StringStruct('ProductVersion', '{version}')])
    ]),
    VarFileInfo([VarStruct('Translation', [1033, 1200])])
  ]
)
"""


def read_version() -> str:
    match = re.search(r'^__version__\s*=\s*"([^"]+)"', INIT.read_text("utf-8"), re.MULTILINE)
    if not match:
        raise SystemExit(f"no __version__ in {INIT}")
    return match.group(1)


def write(out: Path = OUT) -> str:
    version = read_version()
    nums = [int(n) for n in re.findall(r"\d+", version)[:3]]
    a, b, c = (nums + [0, 0, 0])[:3]
    out.write_text(TEMPLATE.format(a=a, b=b, c=c, version=version), encoding="utf-8", newline="\n")
    return version


if __name__ == "__main__":
    print(f"wrote {OUT} for version {write()}")
